export const TABLA_ENTRENADORES = new Table({
  name: process.env.TABLA_ENTRENADORES,
  documentClient: db,
  partitionKey: { name: 'ENTRENADOR_ID', type: 'number' }
});

export const TABLA_ASIGNACIONES = new Table({
  name: process.env.TABLA_ASIGNACIONES,
  documentClient: db,
  partitionKey: { name: 'PISTA_ID', type: 'number' },
  sortKey: { name: 'ENTRENADOR_ID', type: 'number' },
  indexes: {
    PorEntrenador: {
      type: 'global',
      partitionKey: { name: 'ENTRENADOR_ID', type: 'number' },
      sortKey: { name: 'PISTA_ID', type: 'number' }
    }
  }
});

export const MODELO_ENTRENADOR = new Entity({
  name: 'Entrenador',
  table: TABLA_ENTRENADORES,
  entityAttribute: false,
  timestamps: false,
  schema: item({
    entrenadorId: number().key().savedAs('ENTRENADOR_ID'),
    nombre: string().savedAs('NOMBRE'),
    apellidos: string().savedAs('APELLIDOS'),
    email: string().savedAs('EMAIL')
  })
});

export const MODELO_ASIGNACION = new Entity({
  name: 'Asignacion',
  table: TABLA_ASIGNACIONES,
  entityAttribute: false,
  timestamps: false,
  schema: item({
    pistaId: number().key().savedAs('PISTA_ID'),
    entrenadorId: number().key().savedAs('ENTRENADOR_ID'),
    rol: string().savedAs('ROL')
  })
});

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_ENTRENADOR } from '../../models/entrenador-asignacion.model.mjs';

export async function crearEntrenadorRepository(entrenador) {
  await MODELO_ENTRENADOR.build(EntityRepository).put(
    entrenador,
    { condition: { attr: 'entrenadorId', exists: false } }
  );
}

export async function listarEntrenadoresRepository() {
  const { Items = [] } = await MODELO_ENTRENADOR.build(EntityRepository).scan(
    { consistent: true }
  );
  return Items;
}

import { crearEntrenadorRepository, listarEntrenadoresRepository } from './repository.mjs';

export async function crearEntrenadorService(nombre, apellidos, email) {
  const entrenadorId = Date.now();
  const entrenador = { entrenadorId, nombre, apellidos, email };
  await crearEntrenadorRepository(entrenador);
  return entrenador;
}

export function listarEntrenadoresService() {
  return listarEntrenadoresRepository();
}

