import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_PISTA } from '../../models/complejo-pista.model.mjs';
import { MODELO_ENTRENADOR, MODELO_ASIGNACION } from '../../models/entrenador-asignacion.model.mjs';

export async function buscarPistaRepository(pistaId) {
  const { Item } = await MODELO_PISTA.build(EntityRepository).get(
    { pistaId },
    { consistent: true }
  );
  return Item;
}

export async function buscarEntrenadorRepository(entrenadorId) {
  const { Item } = await MODELO_ENTRENADOR.build(EntityRepository).get(
    { entrenadorId },
    { consistent: true }
  );
  return Item;
}

export async function asignarEntrenadorRepository(pistaId, entrenadorId, rol) {
  const asignacion = { pistaId, entrenadorId, rol };
  await MODELO_ASIGNACION.build(EntityRepository).put(
    asignacion,
    { condition: { attr: 'pistaId', exists: false } }
  );
  return asignacion;
}

import { buscarPistaRepository, buscarEntrenadorRepository, asignarEntrenadorRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarEntrenadorService(pistaId, entrenadorId, rol) {
  const pista = await buscarPistaRepository(pistaId);
  const entrenador = await buscarEntrenadorRepository(entrenadorId);
  if (!pista || !entrenador) {
    throw new ReferenciaInexistenteError('No existe la pista o el entrenador');
  }
  return asignarEntrenadorRepository(pistaId, entrenadorId, rol);
}

import { asignarEntrenadorService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const pistaId = Number(event.pathParameters.pistaId);
  const { entrenadorId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarEntrenadorService(pistaId, entrenadorId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El entrenador ya está asignado a esa pista' }) };
    }
    throw error;
  }
}

